package dev.workshopvideo;
import android.graphics.*;import android.widget.*;import android.view.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import dev.workshopvideo.core.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE,application=android.app.Application.class) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PictureSettingsChecks {
 private int pixel(JSONObject options,int color){WallpaperEffects e=new WallpaperEffects();e.options(options);Bitmap input=Bitmap.createBitmap(4,4,Bitmap.Config.ARGB_8888),output=Bitmap.createBitmap(4,4,Bitmap.Config.ARGB_8888);input.eraseColor(color);Paint p=new Paint(3);p.setColorFilter(e.colorFilter());new Canvas(output).drawBitmap(input,0,0,p);int result=output.getPixel(2,2);input.recycle();output.recycle();return result;}
 @Test public void identityBrightnessAndContrastAffectActualAndroidPixels()throws Exception {assertEquals(Color.rgb(80,120,160),pixel(new JSONObject(),Color.rgb(80,120,160)));int dark=pixel(new JSONObject().put("brightness",.5),Color.rgb(100,140,180));assertEquals(50,Color.red(dark),1);assertEquals(70,Color.green(dark),1);int flat=pixel(new JSONObject().put("contrast",0),Color.RED);assertEquals(128,Color.red(flat),1);assertEquals(Color.red(flat),Color.green(flat));assertEquals(Color.green(flat),Color.blue(flat));}
 @Test public void hueAndSaturationTransformActualAndroidPixels()throws Exception {int gray=pixel(new JSONObject().put("saturation",0),Color.RED);assertEquals(Color.red(gray),Color.green(gray));assertEquals(Color.green(gray),Color.blue(gray));int shifted=pixel(new JSONObject().put("hue",90),Color.RED);assertNotEquals(Color.RED,shifted);assertTrue(Color.green(shifted)>0);assertEquals(Color.WHITE,pixel(new JSONObject().put("hue",60),Color.WHITE));}
 private TextView text(View v,String prefix){if(v instanceof TextView&&((TextView)v).getText().toString().startsWith(prefix))return (TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=text(g.getChildAt(i),prefix);if(t!=null)return t;}}return null;}
 @Test public void videoPanelUsesReferenceFieldsAndPersistsEdits()throws Exception {try(var controller=Robolectric.buildActivity(android.app.Activity.class).setup()){var changed=new java.util.concurrent.atomic.AtomicReference<JSONObject>();EffectPanel panel=new EffectPanel(controller.get(),new JSONObject(),true,"video",changed::set);assertNotNull(text(panel,"运动响应"));assertNotNull(text(panel,"播放速度"));assertNotNull(text(panel,"背景颜色"));assertNotNull(text(panel,"亮度"));assertNotNull(text(panel,"对比度"));assertNotNull(text(panel,"色相偏移"));assertNotNull(text(panel,"对齐方式"));assertNull(text(panel,"触摸波纹"));assertNull(text(panel,"漂浮粒子"));((Switch)text(panel,"水平镜像")).setChecked(true);assertTrue(changed.get().optBoolean("flip"));((Switch)text(panel,"系统省电模式")).setChecked(false);assertFalse(changed.get().optBoolean("batteryStatic",true));text(panel,"重置视频设置").performClick();assertFalse(changed.get().optBoolean("flip"));assertTrue(changed.get().optBoolean("batteryStatic"));assertEquals(1,changed.get().optDouble("zoom"),0);}}
 @Test public void videoMigrationClearsHiddenLegacyEffectsAndPreservesChoices()throws Exception {JSONObject old=new JSONObject().put("pan",true).put("gyro",true).put("touch",true).put("particles",true).put("rotation",12).put("flip",true).put("batteryStatic",false);JSONObject v=EffectOptions.video(old);assertEquals("scroll",v.optString("motionMode"));assertTrue(v.optBoolean("pan"));assertFalse(v.optBoolean("gyro"));assertFalse(v.optBoolean("touch"));assertFalse(v.optBoolean("particles"));assertEquals(0,v.optDouble("rotation"),0);assertTrue(v.optBoolean("flip"));assertFalse(v.optBoolean("batteryStatic"));assertEquals(1,EffectOptions.video(null).optDouble("zoom"),0);assertEquals(v.toString(),EffectOptions.video(v).toString());}
 @Test public void oldSceneTogglesSurviveNewVideoSettingsSchema()throws Exception {JSONObject old=new JSONObject().put("gyro",true).put("touch",true).put("pan",true).put("xray",true).put("opacity0",.4);JSONObject restored=EffectOptions.normalize(EffectOptions.normalize(old));assertTrue(restored.optBoolean("gyro"));assertTrue(restored.optBoolean("touch"));assertTrue(restored.optBoolean("pan"));assertEquals(.4,restored.optDouble("opacity0"),.001);assertTrue(restored.optBoolean("xray"));}
}
